@Test
void managementCorsAllowsOnlyTheConfiguredExactOrigin() throws Exception {
    var directory = Files.createTempDirectory("ji-relay-cors-");
    try (var relay = new RelayApplication(directory, "127.0.0.1", 0,
            Map.of("JI_RELAY_TERMINAL_BOOTSTRAP", "terminal-only",
                    "JI_RELAY_ALLOWED_ORIGIN", "http://127.0.0.1:4174"))) {
        URI endpoint = URI.create("http://127.0.0.1:" + relay.port() + "/api/v1/auth/challenge");
        HttpClient client = HttpClient.newHttpClient();
        HttpResponse<String> allowed = client.send(HttpRequest.newBuilder(endpoint)
                .header("Origin", "http://127.0.0.1:4174")
                .header("Access-Control-Request-Method", "POST")
                .header("Access-Control-Request-Headers", "content-type")
                .method("OPTIONS", HttpRequest.BodyPublishers.noBody()).build(),
                HttpResponse.BodyHandlers.ofString());
        assertEquals(204, allowed.statusCode());
        assertEquals("http://127.0.0.1:4174",
                allowed.headers().firstValue("Access-Control-Allow-Origin").orElseThrow());
        assertEquals("Origin", allowed.headers().firstValue("Vary").orElseThrow());

        HttpResponse<String> rejected = client.send(HttpRequest.newBuilder(endpoint)
                .header("Origin", "https://attacker.invalid")
                .header("Access-Control-Request-Method", "POST")
                .method("OPTIONS", HttpRequest.BodyPublishers.noBody()).build(),
                HttpResponse.BodyHandlers.ofString());
        assertEquals(403, rejected.statusCode());
        assertNull(rejected.headers().firstValue("Access-Control-Allow-Origin").orElse(null));
    }
}

